import"./chunk-VC46IEJQ.js";var e=(t,i,o,s,l,a,r,h)=>({name:{en:t[0],zh:t[1]},desc:{en:i[0],zh:i[1]},tour:{en:o[0],zh:o[1]},source:{confidence:s,refs:l,book:{en:a[0],zh:a[1]},unknown:{en:r[0],zh:r[1]},interpretation:{en:h[0],zh:h[1]}}});var n={id:"norvos",intro:{en:"An inland Free City on the Noyne, ruled in effect by its bearded priests and governed by its bells. A walled high city crowns a hill, with a low city by the river far below. This scene renders it as a restrained hill-town.",zh:"\u8BFA\u4F5B\u65AF\u662F\u8BFA\u4F0A\u6CB3\u7554\u7684\u5185\u9646\u81EA\u7531\u8D38\u6613\u57CE\u90A6\uFF0C\u5B9E\u9645\u7531\u84C4\u987B\u796D\u53F8\u638C\u6743\uFF0C\u65E5\u5E38\u4F5C\u606F\u542C\u51ED\u949F\u58F0\u3002\u57CE\u5899\u73AF\u7ED5\u7684\u4E0A\u57CE\u9AD8\u8E1E\u5C71\u9876\uFF0C\u4E0B\u57CE\u8FDC\u5728\u6CB3\u8FB9\u3002\u672C\u573A\u666F\u4EE5\u514B\u5236\u7684\u7B14\u89E6\uFF0C\u628A\u5B83\u5448\u73B0\u4E3A\u4E00\u5EA7\u5C71\u57CE\u3002"},notes:{en:"Established: an inland Free City on the Noyne, a tributary of the Rhoyne; bearded priests who hold real power; three great bells named Noom, Narrah and Nyel that regulate daily life. Wiki summaries add a walled high city on the hilltop with the priests' fortress-temple, a low city about 300 feet below by the river, and the Sinner's Steps between them. Invented: the bluff's scale, the wall circuit, the towers and temple forms, and every building.",zh:"\u53EF\u786E\u8BA4\uFF1A\u8BFA\u4F5B\u65AF\u662F\u6D1B\u6069\u6CB3\u652F\u6D41\u8BFA\u4F0A\u6CB3\u7554\u7684\u5185\u9646\u81EA\u7531\u8D38\u6613\u57CE\u90A6\uFF1B\u84C4\u987B\u796D\u53F8\u638C\u63E1\u5B9E\u6743\uFF1B\u4E09\u53E3\u5927\u949F\u52AA\u59C6\u3001\u7EB3\u62C9\u4E0E\u5948\u5C14\u89C4\u5B9A\u7740\u5168\u57CE\u7684\u4F5C\u606F\u3002\u7EF4\u57FA\u6458\u8981\u53E6\u79F0\uFF1A\u5C71\u9876\u662F\u57CE\u5899\u73AF\u7ED5\u7684\u4E0A\u57CE\uFF0C\u796D\u53F8\u7684\u8981\u585E\u795E\u6BBF\u5C31\u5728\u5176\u4E2D\uFF1B\u4E0B\u57CE\u5728\u7EA6\u4E09\u767E\u5C3A\u4E4B\u4E0B\u7684\u6CB3\u8FB9\uFF0C\u4E24\u8005\u4EE5\u201C\u7F6A\u4EBA\u9636\u68AF\u201D\u76F8\u8FDE\u3002\u81EA\u62DF\u90E8\u5206\uFF1A\u9AD8\u5C97\u5C3A\u5EA6\u3001\u57CE\u5899\u8D70\u5411\u3001\u5854\u697C\u4E0E\u795E\u6BBF\u9020\u578B\uFF0C\u4EE5\u53CA\u6240\u6709\u5EFA\u7B51\u3002"},tour:["noyne-river","high-bluff","city-walls","bell-towers","bearded-priests-temple","lower-town","hills-of-norvos"],sources:[{ref:"affc",checked:"memory",note:{en:"A Norvoshi guard's memories of his home city (the bearded priests, the three bells, high and low city) recalled from memory, not re-read.",zh:"\u4E00\u540D\u8BFA\u4F5B\u65AF\u7C4D\u62A4\u536B\u5BF9\u6545\u4E61\u7684\u56DE\u5FC6\uFF08\u84C4\u987B\u796D\u53F8\u3001\u4E09\u53E3\u5927\u949F\u3001\u4E0A\u57CE\u4E0E\u4E0B\u57CE\uFF09\u51ED\u8BB0\u5FC6\u590D\u8FF0\uFF0C\u672A\u91CD\u8BFB\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"Bell names, high city and low city (about 300 ft apart), the Sinner's Steps and the priests' fortress-temple: confirmed via web-search summaries; pages not fetched.",zh:"\u949F\u540D\u3001\u4E0A\u4E0B\u4E24\u57CE\uFF08\u9AD8\u5DEE\u7EA6\u4E09\u767E\u5C3A\uFF09\u3001\u7F6A\u4EBA\u9636\u68AF\u4E0E\u796D\u53F8\u7684\u8981\u585E\u795E\u6BBF\uFF1A\u7ECF\u7F51\u7EDC\u641C\u7D22\u6458\u8981\u5370\u8BC1\uFF0C\u672A\u80FD\u6253\u5F00\u9875\u9762\u3002"}},{ref:"twoiaf",checked:"not-accessed",note:{en:"Background history not re-checked.",zh:"\u80CC\u666F\u5386\u53F2\u672A\u518D\u6838\u5BF9\u3002"}}],landmarks:{"noyne-river":e(["Noyne River","\u8BFA\u4F0A\u6CB3"],["A tributary of the Rhoyne running at the foot of the hill; the low city lies along it.","\u6D1B\u6069\u6CB3\u7684\u652F\u6D41\uFF0C\u6D41\u7ECF\u5C71\u811A\uFF0C\u4E0B\u57CE\u5C31\u6CBF\u6CB3\u800C\u5EFA\u3002"],["The Noyne flows far below, a road for barges.","\u8BFA\u4F0A\u6CB3\u5728\u8FDC\u8FDC\u7684\u5C71\u4E0B\u6D41\u8FC7\uFF0C\u662F\u9A73\u8239\u5F80\u6765\u7684\u6C34\u8DEF\u3002"],"high",["twoiaf","maps"],["Norvos stands on the Noyne, a tributary of the Rhoyne.","\u8BFA\u4F5B\u65AF\u4F4D\u4E8E\u6D1B\u6069\u6CB3\u7684\u652F\u6D41\u8BFA\u4F0A\u6CB3\u7554\u3002"],["Width and navigability.","\u6CB3\u5BBD\u4E0E\u901A\u822A\u6761\u4EF6\u3002"],["A calm green river with a few barges; invented.","\u5E73\u9759\u7684\u78A7\u7EFF\u6CB3\u9762\u4E0E\u51E0\u6761\u9A73\u8239\uFF1B\u7CFB\u81EA\u62DF\u3002"]),"high-bluff":e(["High City","\u4E0A\u57CE"],["The high city crowns a steep hill above the river, where the old nobility live.","\u4E0A\u57CE\u9AD8\u8E1E\u6CB3\u7554\u9661\u5CED\u7684\u5C71\u9876\uFF0C\u662F\u53E4\u8001\u8D35\u65CF\u7684\u5C45\u6240\u3002"],["A sheer bluff lifts the high city above the river.","\u9661\u5CED\u7684\u9AD8\u5C97\u5C06\u4E0A\u57CE\u6258\u5728\u6CB3\u9762\u4E4B\u4E0A\u3002"],"medium",["affc","awoiaf"],["The high city stands on a tall hill, about 300 feet above the low city by the river (wiki summary).","\u4E0A\u57CE\u4F4D\u4E8E\u9AD8\u4E18\u4E4B\u4E0A\uFF0C\u6BD4\u6CB3\u8FB9\u7684\u4E0B\u57CE\u9AD8\u51FA\u7EA6\u4E09\u767E\u5C3A\uFF08\u636E\u7EF4\u57FA\u6458\u8981\uFF09\u3002"],["The hill's exact shape and the route of the Sinner's Steps.","\u5C71\u4E18\u7684\u786E\u5207\u5F62\u72B6\u4E0E\u7F6A\u4EBA\u9636\u68AF\u7684\u8D70\u5411\u3002"],["A plateau only about 34 m above the river, far lower than described, with a steep western face; no stair is modelled.","\u53F0\u5730\u4EC5\u9AD8\u51FA\u6CB3\u9762\u7EA634\u7C73\uFF0C\u8FDC\u4F4E\u4E8E\u4E66\u4E2D\u6240\u8FF0\uFF0C\u897F\u4FA7\u9661\u5CED\uFF1B\u672A\u5EFA\u6A21\u9636\u68AF\u3002"]),"city-walls":e(["City Walls","\u57CE\u5899"],["A stone wall rings the high city, with round towers and one gate toward the road east.","\u77F3\u5899\u73AF\u7ED5\u4E0A\u57CE\uFF0C\u8BBE\u6709\u5706\u5854\uFF0C\u4E00\u5EA7\u57CE\u95E8\u901A\u5411\u4E1C\u53BB\u7684\u5927\u9053\u3002"],["Mighty walls follow the edge of the hilltop.","\u575A\u56FA\u7684\u57CE\u5899\u6CBF\u7740\u5C71\u9876\u8FB9\u7F18\u800C\u7B51\u3002"],"medium",["affc","awoiaf"],["The high city is ringed by mighty stone walls (wiki summary).","\u4E0A\u57CE\u7531\u575A\u56FA\u7684\u77F3\u5899\u73AF\u7ED5\uFF08\u636E\u7EF4\u57FA\u6458\u8981\uFF09\u3002"],["Wall height, circuit and gates.","\u57CE\u5899\u9AD8\u5EA6\u3001\u5468\u957F\u4E0E\u57CE\u95E8\u3002"],["A single irregular oval with one gate; invented.","\u4E00\u5708\u4E0D\u89C4\u5219\u7684\u692D\u5706\u57CE\u5899\uFF0C\u53EA\u8BBE\u4E00\u95E8\uFF1B\u7CFB\u81EA\u62DF\u3002"]),"bell-towers":e(["Bell Towers","\u949F\u697C"],["Open belfries rise above the roofs; three great bells tell the Norvoshi when to rise, work, pray and sleep.","\u655E\u53E3\u949F\u5BA4\u9AD8\u51FA\u5C4B\u9876\u3002\u4E09\u53E3\u5927\u949F\u544A\u8BC9\u8BFA\u4F5B\u65AF\u4EBA\u4F55\u65F6\u8D77\u5E8A\u3001\u52B3\u4F5C\u3001\u7948\u7977\u4E0E\u5C31\u5BDD\u3002"],["Noom, Narrah and Nyel: three bells rule the Norvoshi day.","\u52AA\u59C6\u3001\u7EB3\u62C9\u3001\u5948\u5C14\uFF0C\u4E09\u53E3\u5927\u949F\u4E3B\u5BB0\u7740\u8BFA\u4F5B\u65AF\u4EBA\u7684\u4E00\u5929\u3002"],"high",["affc","awoiaf"],["Norvos has three named bells, Noom, Narrah and Nyel, each with its own voice, which regulate daily life; they are counted among the Wonders Made by Man.","\u8BFA\u4F5B\u65AF\u6709\u4E09\u53E3\u5404\u6709\u540D\u5B57\u7684\u5927\u949F\u2014\u2014\u52AA\u59C6\u3001\u7EB3\u62C9\u4E0E\u5948\u5C14\uFF0C\u58F0\u97F3\u5404\u5F02\uFF0C\u89C4\u5B9A\u7740\u65E5\u5E38\u4F5C\u606F\uFF1B\u5B83\u4EEC\u4F4D\u5217\u201C\u4EBA\u9020\u5947\u89C2\u201D\u4E4B\u4E00\u3002"],["Where the bells hang and what their towers look like.","\u5927\u949F\u60AC\u4E8E\u4F55\u5904\uFF0C\u949F\u697C\u662F\u4F55\u6A21\u6837\u3002"],["Four towers of different heights; invented.","\u56DB\u5EA7\u9AD8\u4F4E\u4E0D\u4E00\u7684\u949F\u697C\uFF1B\u7CFB\u81EA\u62DF\u3002"]),"bearded-priests-temple":e(["Priests' Temple","\u796D\u53F8\u795E\u6BBF"],["The bearded priests' fortress-temple in the high city, the true seat of power.","\u4E0A\u57CE\u4E2D\u84C4\u987B\u796D\u53F8\u7684\u8981\u585E\u795E\u6BBF\uFF0C\u662F\u771F\u6B63\u7684\u6743\u529B\u6240\u5728\u3002"],["The bearded priests rule Norvos in all but name.","\u84C4\u987B\u796D\u53F8\u867D\u65E0\u5176\u540D\uFF0C\u5374\u662F\u8BFA\u4F5B\u65AF\u771F\u6B63\u7684\u7EDF\u6CBB\u8005\u3002"],"medium",["affc","awoiaf"],["The bearded priests hold real power and train temple guards; a wiki summary places their great fortress-temple in the high city.","\u84C4\u987B\u796D\u53F8\u63E1\u6709\u5B9E\u6743\uFF0C\u5E76\u8BAD\u7EC3\u795E\u6BBF\u536B\u58EB\uFF1B\u7EF4\u57FA\u6458\u8981\u79F0\u4ED6\u4EEC\u5B8F\u5927\u7684\u8981\u585E\u795E\u6BBF\u4F4D\u4E8E\u4E0A\u57CE\u3002"],["The temple's appearance and the faith's doctrines.","\u795E\u6BBF\u7684\u5916\u89C2\u4E0E\u6559\u4E49\u3002"],["A columned hall with a gabled slate roof, not fortified; invented.","\u4E00\u5EA7\u5E26\u5C71\u5899\u77F3\u677F\u9876\u7684\u67F1\u5ECA\u5927\u5385\uFF0C\u672A\u4F5C\u8981\u585E\u5316\u5904\u7406\uFF1B\u7CFB\u81EA\u62DF\u3002"]),"lower-town":e(["Lower Town","\u4E0B\u57CE"],["Houses and lanes on the slopes below the walls.","\u57CE\u5899\u4E4B\u4E0B\u5C71\u5761\u4E0A\u7684\u623F\u5C4B\u4E0E\u5C0F\u5DF7\u3002"],["Below the walls the lanes spill down the hill.","\u57CE\u5899\u4E4B\u4E0B\uFF0C\u5C0F\u5DF7\u987A\u5C71\u52BF\u800C\u4E0B\u3002"],"low",["affc","awoiaf"],["The low city lies at the foot of the hill by the river, linked to the high city by the Sinner's Steps.","\u4E0B\u57CE\u4F4D\u4E8E\u5C71\u811A\u6CB3\u7554\uFF0C\u7ECF\u7F6A\u4EBA\u9636\u68AF\u4E0E\u4E0A\u57CE\u76F8\u8FDE\u3002"],["Its streets, size and look.","\u8857\u9053\u3001\u89C4\u6A21\u4E0E\u6837\u8C8C\u3002"],["A loose scatter of houses east of the walls along the road, not by the river as in the books.","\u57CE\u5899\u4EE5\u4E1C\u6CBF\u8DEF\u6563\u5E03\u7684\u623F\u5C4B\uFF1B\u4F4D\u7F6E\u4E0E\u4E66\u4E2D\u201C\u4E0B\u57CE\u5728\u6CB3\u8FB9\u201D\u5E76\u4E0D\u76F8\u7B26\u3002"]),"hills-of-norvos":e(["Hills of Norvos","\u8BFA\u4F5B\u65AF\u4E18\u9675"],["Rolling hills of oak and pine around the city.","\u57CE\u5468\u8D77\u4F0F\u7684\u4E18\u9675\uFF0C\u6A61\u6811\u4E0E\u677E\u6797\u76F8\u95F4\u3002"],["The city sits among hills, far from the sea.","\u57CE\u5E02\u5750\u843D\u5728\u7FA4\u4E18\u4E4B\u95F4\uFF0C\u8FDC\u79BB\u5927\u6D77\u3002"],"medium",["maps","twoiaf"],["The city lies in hill country, inland from the sea.","\u57CE\u5E02\u4F4D\u4E8E\u8FDC\u79BB\u6D77\u5CB8\u7684\u4E18\u9675\u5730\u5E26\u3002"],["Vegetation and relief.","\u690D\u88AB\u4E0E\u5730\u52BF\u3002"],["Oak and pine cover; invented.","\u6A61\u6811\u4E0E\u677E\u6797\uFF1B\u7CFB\u81EA\u62DF\u3002"])}};export{n as default};
